/* Adapt the supplied reference to Doitkit's existing workflow. */
const doitkitTokens={version:'2.5-design',reference:'DESIGN.md / LikeLion observed desktop style; adapted to Doitkit',colors:{primary:'#222222',canvas:'#FFFFFF',surface:'#FFFFFF',text:'#222222',muted:'#737373',mutedSecondary:'#A3A3A3',line:'#E5E5E5',promo:'#FCF4EE',attention:'#FF6000',brand:'#B77BA2'},font:{family:'Noto Sans KR',title:32,section:20,body:14,caption:12},spacing:{unit:8,panel:24,content:40},radius:{panel:16,button:9999},frames:{console:[1440,960],client:[1440,960],mobile:[390,844]},components:['BrandSwitcher','StartGuide','FilterPill','EventRow','TemplateCard','PromptComposer','LayerPanel','EditableCanvas','PropertiesPanel']};
home=function(){return shell(`${startGuide()}<div class="desk-heading"><div><h1>행사 운영, 한눈에.</h1><p class="sub">${state.brandFilter==='전체'?'모든 브랜드의 진행 상황을 확인하고 다음 작업을 이어가세요.':esc(brands.find(b=>b.id===state.brandFilter)?.name||'')+'의 진행 상황을 확인하세요.'}</p></div><button class="btn" data-action="new">＋ 행사 만들기</button></div><div class="desk-tasks"><button data-go="operate"><div><strong>발송 실패 확인</strong><small>루미에르 성수 팝업</small></div><b>${state.retried?'0':'5'}</b></button><button data-go="review"><div><strong>시안 의견</strong><small>브랜드사와 검토 중</small></div><b>2</b></button><button data-go="publish"><div><strong>게시 준비</strong><small>확정된 시안을 확인하세요</small></div><b>1</b></button></div><section class="desk-events"><div class="panel-head"><h2>진행 중·예정 행사</h2><a href="#events" class="text-link">전체 행사 →</a></div><div class="filters"><select id="event-brand-filter" class="event-brand-filter" aria-label="행사 브랜드 필터">${brandOptions(true)}</select>${statusFilterChips(true)}</div>${eventTable()}</section><div class="desk-footer"><p>이번 달 행사 패스 <strong>2건</strong> · 전체 브랜드 발송비 <strong>412,300원</strong><button class="text-link" data-action="usage" style="margin-left:16px">내역 보기 →</button></p><a href="#workspace">브랜드 워크스페이스 관리 →</a></div>`)};
const referenceDesign=design;design=function(){return referenceDesign().replace('#6858E8','#222222').replace('#F5F6F8','#FFFFFF').replace('#202634','#222222').replace('제목 28 / 섹션 17 / 본문 14 / 보조 12px','제목 32 / 섹션 20 / 본문 14 / 보조 12px').replace('Button / Status pill / Brand badge','Brand switcher / Filter pill / Layer panel').replace('<h2>공통 디자인 토큰</h2>','<h2>공통 디자인 토큰</h2><p class="small dim">DESIGN.md의 중립 색상, 얇은 구분선, 크림색 안내 영역을 두잇킷에 적용했습니다. 기능 상태와 반응형은 두잇킷의 자체 설계입니다.</p>')};
const referenceAction=action;action=function(a,n){if(a==='tokens'){download('doitkit-design-tokens.json',JSON.stringify(doitkitTokens,null,2));return}referenceAction(a,n)};render();
